import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Platform Abstractions","description":"","frontmatter":{"title":"Platform Abstractions","type":"adr","date":"2026-08-25T00:00:00.000Z","status":"proposed","status_note":"Accepted — one `handl-platform` crate holds the core contracts; capabilities are data."},"headers":[],"relativePath":"handl/project/adrs/0031-platform-abstractions.md","filePath":"vendored/handl/project/adrs/0031-platform-abstractions.md"}'),a={name:`handl/project/adrs/0031-platform-abstractions.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0031-platform-abstractions" tabindex="-1">ADR-0031: Platform Abstractions <a class="header-anchor" href="#adr-0031-platform-abstractions" aria-label="Permalink to “ADR-0031: Platform Abstractions”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>One crate, <code>handl-platform</code></strong>, holds the core contracts as modules: <code>capability</code>, <code>plugin</code>, <code>extension</code>, <code>kit</code>, <code>host</code>, <code>boundary</code>.</li><li><strong><code>CapabilityMetadata</code> is opaque <code>serde_json::Value</code></strong>; the platform defines no CLI-specific keys — each host interprets the object.</li><li><strong>Default capabilities ship as <code>handl-ext-*</code> plugins</strong> (fmt, lint, typecheck, eval, compile, build, extension, kit, plugin); concrete command semantics live only there.</li><li><strong>Hosts generate their surface from capability metadata</strong>; the CLI does not know <code>fmt</code>/<code>lint</code>/<code>plugin</code>, and the management capabilities operate on the platform registries, not as CLI special cases.</li><li><strong>Existing crates migrate</strong>: <code>host-cli-plugin</code> empties into <code>platform::plugin</code>; <code>compiler-pass-*</code> become pass hosts; <code>vm</code> aligns with <code>platform::host</code>.</li><li><strong>Out of scope</strong> until the layer is stable: <code>Framework</code>, <code>Middleware</code>, <code>Rpc</code>, and the <code>handl-document</code> unification.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Each host had its own plugin/registry types and the CLI hardcoded its subcommands, so a new host or capability meant a new abstraction. One platform crate with opaque capability metadata lets every host surface the same capability differently.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Separate <code>handl-plugin</code>/<code>extension</code>/<code>framework</code> crates</strong> — modules first.</li><li><strong>A CLI-specific metadata schema</strong> — metadata is opaque.</li><li><strong>Command semantics in the CLI</strong> — they live in <code>handl-ext-*</code>.</li><li><strong>Framework/RPC work now</strong> — deferred until the contracts settle.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Hosts are thin; capabilities are plugins with metadata.</li><li>Management commands use the same registries as everything else.</li><li>The migration is mechanical: move types, generalize, align hosts.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>crates/handl-platform/</code> — the six modules.</li><li><code>crates/handl-ext-*/</code> — the default capabilities.</li><li>Host tests that generate subcommands from metadata.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+Module contents, metadata example, built-in capabilities and migrations: +<a href="./../design/0031-platform-abstractions.html"><code>design/0031-platform-abstractions.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};